package in.foodcart.api; import in.foodcart.data.*; import in.foodcart.service.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/orders") public class OrderController {private final CheckoutService checkout;private final AuthService auth;private final OrderRepository orders;public OrderController(CheckoutService c,AuthService a,OrderRepository o){checkout=c;auth=a;orders=o;}@PostMapping public OrderEntity create(@RequestHeader("Authorization") String header,@RequestBody CheckoutService.Request request){return checkout.create(auth.actor(header,"CUSTOMER"),request);}@GetMapping("/{id}") public OrderEntity get(@RequestHeader("Authorization") String header,@PathVariable String id){String customer=auth.actor(header,"CUSTOMER");OrderEntity o=orders.findById(id).orElseThrow(()->new IllegalArgumentException("Order not found"));if(!o.customerId.equals(customer))throw new SecurityException("Order not found");return o;}}
